#include <stdio.h>

#define MAXN 200000
#define INF 1000000000

int main(void) {
    int n;
    int a[MAXN];

    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        if (a[i] == -1) a[i] = INF;
    }

    for (int i = 1; i < n; i++) {
        if (a[i - 1] + 1 < a[i]) a[i] = a[i - 1] + 1;
    }

    for (int i = n - 2; i >= 0; i--) {
        if (a[i + 1] + 1 < a[i]) a[i] = a[i + 1] + 1;
    }

    for (int i = 0; i < n; i++) {
        if (i) printf(" ");
        printf("%d", a[i]);
    }
    printf("\n");

    return 0;
}
